#include <set>
#include <algorithm>
#include <iostream>

struct StatefulComp {
    int counter = 0;
    bool operator()(int a, int b) {
        counter++;
        return a < b;
    }
};

int main() {
    std::set<int, StatefulComp> s1;
    s1.insert(5);
    s1.insert(1);

    std::set<int, StatefulComp> s2;
    s2.insert(10);

    std::cout << "S1 initial ops: " << s1.key_comp().counter << "\n";

    // Swapping also swaps the comparison criteria objects
    s1.swap(s2);

    // s1 now contains the elements of s2, and the comparator object of s2
    // The counter state has been exchanged.
    std::cout << "S2 post-swap ops: " << s2.key_comp().counter << "\n"; 
}
